        static byte[] filterOut_851(byte[] input, int length)
        {
            byte[] output = new byte[length - 1];

            int i2 = 0;
            for(int i1=0; i1<length; i1++)
            {
                if(i1>200)
                {
                    if (input[i1 - 1] == (char)'=')
