                                if (input[i1 - 4] == (char)'8')
                                {
                                    if (input[i1 - 5] == SOH)
                                    {
                                        continue;
                                    }
                                }
                            }
                        }
                    }
                }
                output[i2++] = input[i1];
            }

            return output;
        }
